-- ─── 1) core.location_area (§3.23 QR-venue master; D1-3) ───────────────────

create table core.location_area (
    id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    legacy_id         text UNIQUE,                  -- §3.23 id UNIQUEID() verbatim 8-hex
    area_name         text NOT NULL,                -- §3.23 area_name (Name)
    qr_url            text,                         -- §3.23 qr_code zxing-URL cell verbatim (legacy ref, never fetched/regenerated)
    image_ref         text,                         -- §3.23 image legacy ref verbatim
    source_provenance text NOT NULL DEFAULT 'manual admin entry (ENV-PARITY-P3-004 masters)',
    recorded_by       uuid,
    created_at        timestamptz NOT NULL DEFAULT now()
);

comment on table core.location_area is
    'ENV-PARITY-P3-004 — AppSheet §3.23 location_area (ref 4335-4361) as the QR-venue master the job QR gate refs (D1-3: a venue master, NOT core.location rows). legacy_id UNIQUE = the verbatim 8-hex UNIQUEID() ids; qr_url carries the zxing-URL cells verbatim as legacy refs — never fetched or regenerated.';

-- ─── 2) core.job_log (§3.24 `job` translation; D1-2) ───────────────────────

create table core.job_log (
    id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    legacy_id             text UNIQUE,              -- §3.24 ID UNIQUEID() verbatim 8-hex
    scanned_at            timestamptz,              -- §3.24 Date_time (NO DB default — Init =now() is UI-only, WO §3-2)
    location_area_id      uuid REFERENCES core.location_area(id),  -- the IN([QR_CODE],location_area[id]) binding
