    location_name         text,                     -- §3.24 location_name recorded history text verbatim
    lat                   numeric,                  -- §3.24 location LatLong split (haversine input)
    lng                   numeric,                  -- §3.24 location LatLong split (haversine input)
    practitioner_id       uuid REFERENCES core.personnel(id),  -- §3.24 practician — resolved UUID-or-NULL ONLY (PII hard pin)
    practitioner_legacy_id text,                    -- PII pin: ships NULL on every row — the raw ID is national-ID class, NEVER stored
    working               text,                     -- §3.24 working EnumList — the verbatim " , "-joined form (D1-4)
    image_ref             text,                     -- §3.24 image legacy filename refs verbatim (new writes: house attachment path)
    issue                 text,                     -- §3.24 issue verbatim
