-- ─── 3) the server haversine geofence gate (the row's own pin) ─────────────
-- D1-6 RULED: BEFORE INSERT trigger (gates EVERY insert path) over the
-- checked-RPC alternative (gates only its callers). D1-5 CONFIRMED 0.7 km
-- as the write-gate bound — the plan row's OWN pin ("geofence ≤0.7 กม.
-- (server haversine)"); the AppSheet virtual-check <=2 bound is a
-- display-layer artifact, recorded verbatim in the WO, never reconciled,
-- never an ENV gate.

create or replace function core.fn_job_log_geofence() returns trigger
language plpgsql
as $fn$
declare
    v_distance_km numeric;
begin
    -- The guarded history-seed exemption (D1-6): the 1102 recorded rows
    -- carry their recorded lat/lng verbatim — the AppSheet Valid If
    -- already gated them at entry; re-validation would fabricate
    -- rejections of history. Only THIS migration's pinned seed
    -- provenance marker is honored; every other NEW write is gated.
    if new.source_provenance like 'workbook 1Hluhfryn2uMdK8nQ2kRJyLI3q-ZbrwgBgveDbhJlerw tab job (%' then
        return new;
    end if;
    -- Unknown ≠ passed: blank/unknown coordinates fail the gate exactly
    -- like AppSheet's distance([uthai_locate],[location])<=0.7 on blank.
    if new.lat is null or new.lng is null then
        raise exception 'ฮั่นแน่...เข้ามาทำงานก่อน';
    end if;
    v_distance_km := 6371.0088 * 2 * asin(sqrt(
        power(sin(radians(new.lat - 14.361183) / 2), 2)
        + cos(radians(14.361183)) * cos(radians(new.lat))
          * power(sin(radians(new.lng - 100.645474) / 2), 2)
    ));
    if v_distance_km > 0.7 then
        raise exception 'ฮั่นแน่...เข้ามาทำงานก่อน';
    end if;
    return new;
end;
$fn$;

comment on function core.fn_job_log_geofence() is
    'P3.4 — the server haversine write gate (the plan row''s own pin): rejects NEW core.job_log writes farther than 0.7 km from the verbatim hospital pin LATLONG(14.361183, 100.645474) with the verbatim AppSheet error ฮั่นแน่...เข้ามาทำงานก่อน. Blank coordinates reject too (unknown ≠ passed). The pinned seed provenance marker (workbook 1Hluhfry… tab job) is the ONLY history exemption (D1-6: never retroactively re-validated). The AppSheet virtual Distance <=2 check is a display-layer artifact — recorded, never an ENV gate (D1-5).';

drop trigger if exists trg_job_log_geofence on core.job_log;
create trigger trg_job_log_geofence
    before insert on core.job_log
    for each row
    execute function core.fn_job_log_geofence();

