drop policy if exists location_area_update_admin on core.location_area;
create policy location_area_update_admin
    on core.location_area for update to authenticated
    using (core.fn_is_admin())
    with check (core.fn_is_admin());

drop policy if exists location_area_delete_admin on core.location_area;
create policy location_area_delete_admin
    on core.location_area for delete to authenticated
    using (core.fn_is_admin());

grant select, insert, update, delete on core.location_area to authenticated;

alter table core.job_log enable row level security;

drop policy if exists job_log_select on core.job_log;
create policy job_log_select
    on core.job_log for select to authenticated
